import { useContext } from 'react';

import { useStoreSelector } from '../../../../core/store/selector.js';
import { TimeseriesChartStateContext } from '../../context/TimeseriesChartState.context.js';
import { TimeseriesChartState } from '../../types/state.js';

export const useSelector = <T>(
  selector: (state: TimeseriesChartState) => T,
): T => useStoreSelector(TimeseriesChartStateContext, selector);

export const useZoomState = () =>
  useSelector((state: TimeseriesChartState) => state.zoom);

export const useOverlaysState = () =>
  useSelector((state: TimeseriesChartState) => state.overlays);

export const useFilteredSeriesIdsState = () =>
  useSelector((state: TimeseriesChartState) => state.filteredSeriesIds);

export const useInteractionsDisabledState = () =>
  useSelector((state: TimeseriesChartState) => state.interactionsDisabled);

export const useHighlightedSeriesIdsState = () =>
  useSelector((state: TimeseriesChartState) => state.highlightedSeriesIds);

export const useCurrentDomainState = () =>
  useSelector((state: TimeseriesChartState) => state.currentDomain);

export const useAnnotationsState = () =>
  useSelector((state: TimeseriesChartState) => state.annotations);

export const useThresholdsState = () =>
  useSelector((state: TimeseriesChartState) => state.thresholds);

export const useSetState = () => {
  const { setState } = useContext(TimeseriesChartStateContext);

  return setState;
};
